package com.gymmind.workout.application;
import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.exercise.domain.repository.ExerciseRepository; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.member.domain.repository.MemberRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import com.gymmind.workout.domain.model.*; import com.gymmind.workout.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map;
@Service public class DefaultWorkoutRecordService implements WorkoutRecordService { private final WorkoutRecordRepository records; private final WorkoutSetRepository sets; private final MemberRepository members; private final ExerciseRepository exercises; private final AuditRecorder audit; public DefaultWorkoutRecordService(WorkoutRecordRepository r,WorkoutSetRepository s,MemberRepository m,ExerciseRepository e,AuditRecorder a){records=r;sets=s;members=m;exercises=e;audit=a;} @Override @Transactional public WorkoutRecordView create(CurrentActor actor,CreateWorkoutRecordCommand c){if(actor==null||actor.tenantId()==null||!actor.roles().contains(RoleCode.MEMBER)||!actor.hasPermission("workout-record:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!actor.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);Long memberId=members.findByTenantIdAndUserId(actor.tenantId(),actor.userId()).map(com.gymmind.member.domain.model.Member::getId).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(c.duration()<0||c.calories()<0||c.sets()==null||c.sets().isEmpty()||c.notes()==null||c.notes().isBlank()||c.workoutDate()==null)throw new BusinessException(ErrorCode.VALIDATION_FAILED);for(var s:c.sets()){if(s==null||s.exerciseId()==null||s.setNumber()<=0||s.weight()<0||s.reps()<0||s.duration()<0)throw new BusinessException(ErrorCode.VALIDATION_FAILED);exercises.findByTenantIdAndId(actor.tenantId(),s.exerciseId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));}WorkoutRecord r=records.save(WorkoutRecord.create(actor.tenantId(),memberId,c.planId(),c.workoutDate(),c.duration(),c.calories(),c.notes()));for(var s:c.sets())sets.save(WorkoutSet.create(r,s.exerciseId(),s.setNumber(),s.weight(),s.reps(),s.duration(),s.completed()));audit.record(new AuditEvent("WORKOUT_RECORD_CREATED","WORKOUT_RECORD",r.getId(),AuditResult.SUCCESS,"workout-record-service",Map.of("resourceName","workout-record")));return new WorkoutRecordView(r.getId(),r.getTenantId(),r.getMemberId(),r.getPlanId(),r.getWorkoutDate(),r.getDuration(),r.getCalories(),r.getNotes(),r.getStatus());} }
